import { Configuration, DataCloudApi } from "./lib";
import { DataCloudMiddleware } from "./utils/dataCloudMiddleware";
import * as runtime from "./lib";

/**
 * 
 * @param tenantId The tenant ID of a data cloud instance.
 * @param appSourceId The app source id of a data cloud instance.
 * @returns Tenant ID that is assigned for the Data Cloud Org.
 */
export function initDataCloudSdk(tenantId: string, appSourceId: string) {
    if(!tenantId) {
        throw new runtime.RequiredError('tenantId', 'tenantId is empty.');
    }

    if(!appSourceId) {
        throw new runtime.RequiredError('appSourceId', 'appSourceId is empty.');
    }

    const eventsPath = `web/events/${appSourceId}`;
    return new DataCloudApi(new Configuration({
        basePath: `https://${tenantId}.c360a.salesforce.com/${eventsPath}`,
        middleware: [new DataCloudMiddleware()]
    }));
}
